}

function normalizeVerificationStatus(status) {
  const normalized = String(status || 'UNVERIFIED').toUpperCase();
  return ['VERIFIED', 'PARTIALLY_VERIFIED', 'UNVERIFIED', 'CONTRADICTED'].includes(normalized)
