function runEntireCommand(args, repoPath) {
  const cwd = repoPath || process.cwd();
  const argv = Array.isArray(args) ? args.map(String) : String(args).split(/\s+/).filter(Boolean);
  const command = ['entire', ...argv].join(' ');
