      impact: impactInfo,
      source: graphResult.success ? 'entire-graph' : 'entire-graph-unavailable'
    });
  }
  return results;
}"},{"rank":2,"score":47.0186,"file_path":"backend/index.js","start_line":11,"end_line":15,"focus_line":13,"snippet_start_line":11,"snippet_end_line":15,"language":"JavaScript","signals":["body","symbol-usage"],"snippet":"  getCheckpointExplanation, getCheckpointTranscript, searchCheckpoints,
