282	export function normalizeDatabricksHost(rawHost, env = process.env) {
283	  const raw = String(rawHost || '').trim();
284	  if (!raw) return { ok: false, error: 'Databricks host is not configured' };
285	  if (raw.length > 300 || /[\0\s]/.test(raw)) {
286	    return { ok: false, error: 'Databricks host is invalid' };
287	  }
288	
289	  const candidate = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
290	  let url;
291	  try {
292	    url = new URL(candidate);
293	  } catch {
294	    return { ok: false, error: 'Databricks host is invalid' };
295	  }
296	
297	  if (url.username || url.password) {
298	    return { ok: false, error: 'Databricks host must not include embedded credentials' };
299	  }
300	
301	  if (!['https:', 'http:'].includes(url.protocol)) {
302	    return { ok: false, error: 'Databricks host must use HTTP or HTTPS' };
303	  }
304	
305	  if (url.protocol !== 'https:' && !envFlag('DATABRICKS_ALLOW_INSECURE_HOST', false, env)) {
306	    return { ok: false, error: 'Databricks host must use HTTPS' };
307	  }
308	
309	  if (isPrivateHostname(url.hostname) && !envFlag('DATABRICKS_ALLOW_PRIVATE_HOST', false, env)) {
310	    return { ok: false, error: 'Databricks host must not target localhost or private network addresses' };
311	  }
312	
313	  return {
314	    ok: true,
315	    baseUrl: url.origin,
316	    hostname: url.hostname,
317	    safeHost: maskHostname(url.hostname)
318	  };
319	}

